<template>
  <div class="dc-page"><div class="dc-container">
    <button class="dc-back" @click="router.back()"><ArrowLeft :size="16"/>返回</button>
    <section v-if="data" class="detail-head dc-card">
      <div class="head-main"><div class="head-tags"><span class="dc-chip">{{data.layerCode}}</span><span class="status">● {{data.status==='ONLINE'?'在用':data.status}}</span></div><h1>{{data.bizName}}</h1><code class="dc-tech">{{data.tableName}}</code><p>{{data.catalogCode}} · {{data.assetId}}</p></div>
      <div class="head-actions"><el-button @click="copyName"><Copy :size="15"/>复制表名</el-button><el-button><GitFork :size="15"/>查看关系</el-button><el-button type="primary"><Sparkles :size="15"/>问这张表</el-button></div>
    </section>

    <section v-if="data" class="meta-strip dc-card">
      <div><span>技术负责人</span><b>{{data.techOwner||'—'}}</b></div><div><span>业务负责人</span><b>{{data.bizOwner||'—'}}</b></div><div><span>更新频率</span><b>{{data.updateFreq||'—'}}</b></div><div><span>最近更新</span><b>{{formatTime(data.dataUpdatedAt)}}</b></div><div><span>工作空间</span><b>{{data.workspaceCode||'—'}}</b></div>
    </section>

    <div v-if="data" class="detail-layout">
      <section class="dc-card detail-main">
        <el-tabs v-model="tab">
          <el-tab-pane label="基本信息" name="overview"><div class="section-block"><span class="dc-eyebrow">OVERVIEW</span><h2>资产定义</h2><p>{{data.bizDefinition||'暂无业务定义。'}}</p><div class="caliber"><b>统计口径</b><p>{{data.statCaliber||'暂无统计口径。'}}</p></div><div class="kv-grid"><div><span>数据粒度</span><b>{{data.grain||'—'}}</b></div><div><span>数据来源</span><b>{{data.dataSourceDesc||'—'}}</b></div><div><span>使用说明</span><b>{{data.usageNotes||'—'}}</b></div><div><span>所属目录</span><b>{{data.catalogCode||'—'}}</b></div></div></div></el-tab-pane>
          <el-tab-pane label="字段信息" name="columns"><div class="table-actions"><b>{{columns.length}} 个字段</b><el-input v-model="columnKeyword" clearable placeholder="搜索字段"/></div><div class="dc-table-wrap"><table class="dc-table"><thead><tr><th>序号</th><th>字段名</th><th>中文名</th><th>类型</th><th>业务定义</th><th>标准/码表</th></tr></thead><tbody><tr v-for="c in filteredColumns" :key="c.assetId"><td>{{c.ordinalNo}}</td><td><RouterLink class="field-link" :to="`/fields/${c.assetId}`"><code class="dc-tech">{{c.columnName}}</code></RouterLink></td><td><RouterLink class="field-link" :to="`/fields/${c.assetId}`">{{c.cnName||'—'}}</RouterLink></td><td>{{c.dataType}}</td><td>{{c.bizDefinition||'—'}}</td><td><RouterLink v-if="c.standardNo" :to="`/standards/${c.standardNo}`" class="dc-chip">{{c.standardNo}}</RouterLink><RouterLink v-else-if="c.codeTableNo" :to="`/code-tables/${c.codeTableNo}`" class="dc-chip">{{c.codeTableNo}}</RouterLink><span v-else>—</span></td></tr></tbody></table></div></el-tab-pane>
          <el-tab-pane label="常用 SQL" name="sql"><div v-if="sqlRows.length" class="sql-list"><article v-for="x in sqlRows" :key="x.sqlCode"><div><span class="dc-chip">{{x.dialect}}</span><h3>{{x.title}}</h3><p>{{x.question}}</p></div><pre>{{x.sqlText}}</pre></article></div><div v-else class="dc-empty">暂无常用 SQL。</div></el-tab-pane>
          <el-tab-pane label="变更记录" name="changes"><div class="timeline" v-if="changes.length"><article v-for="x in changes" :key="x.id"><span>{{formatTime(x.changeDate)}}</span><div><b>{{x.changeType}}</b><p>{{x.content}}</p><small>{{x.changedBy||'系统'}}</small></div></article></div><div v-else class="dc-empty">暂无变更记录。</div></el-tab-pane>
          <el-tab-pane label="血缘关系" name="relations"><div class="relation-summary"><div><span>上游</span><strong>{{relations.upstream?.length||0}}</strong></div><ArrowRight/><div class="current-node"><span>当前资产</span><strong>{{data.layerCode}}</strong></div><ArrowRight/><div><span>下游</span><strong>{{relations.downstream?.length||0}}</strong></div></div><div class="relation-list"><article v-for="x in [...(relations.upstream||[]),...(relations.downstream||[])]" :key="`${x.srcAssetId}-${x.dstAssetId}`"><RouterLink :to="`/datasets/${x.srcAssetId}`"><b>{{x.srcName}}</b></RouterLink><ArrowRight :size="14"/><RouterLink :to="`/datasets/${x.dstAssetId}`"><b>{{x.dstName}}</b></RouterLink><span>{{x.taskName}}</span></article></div></el-tab-pane>
