        <section class="dc-card side-card"><span class="dc-eyebrow">IDENTITY</span><h3>稳定身份</h3><dl><div><dt>Asset ID</dt><dd>{{data.assetId}}</dd></div><div><dt>物理表名</dt><dd class="dc-tech">{{data.tableName}}</dd></div><div><dt>生命周期</dt><dd>{{data.status}}</dd></div></dl></section>
        <section class="dc-card side-card"><span class="dc-eyebrow">TAGS</span><h3>资产标签</h3><div class="tag-wrap"><span v-for="x in tags" :key="x.code" class="dc-chip">{{x.name}}</span><span v-if="!tags.length" class="dc-muted">暂无标签</span></div></section>
      </aside>
    </div>
    <div v-else class="dc-empty">正在加载数据集详情…</div>
  </div></div>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { RouterLink, useRoute, useRouter } from 'vue-router'
import { ArrowLeft, ArrowRight, Copy, GitFork, Sparkles } from 'lucide-vue-next'
import { ElMessage } from 'element-plus'
import { activityApi, assetApi } from '@/api/client'
const route=useRoute(); const router=useRouter(); const data=ref<any|null>(null); const columns=ref<any[]>([]); const tags=ref<any[]>([]); const sqlRows=ref<any[]>([]); const changes=ref<any[]>([]); const relations=reactive<any>({upstream:[],downstream:[]}); const tab=ref('overview'); const columnKeyword=ref('')
const filteredColumns=computed(()=>{const k=columnKeyword.value.trim().toLowerCase();return k?columns.value.filter(x=>`${x.columnName} ${x.cnName||''} ${x.bizDefinition||''}`.toLowerCase().includes(k)):columns.value})
function formatTime(v?:string){return v?String(v).replace('T',' ').slice(0,16):'—'}
async function copyName(){if(!data.value)return;await navigator.clipboard.writeText(data.value.tableName);ElMessage.success('已复制表名')}
onMounted(async()=>{const id=String(route.params.id); data.value=await assetApi.table(id); await Promise.allSettled([assetApi.columns({dataset_id:id,limit:500}).then((v:any)=>columns.value=v),assetApi.tags(id).then((v:any)=>tags.value=v),assetApi.commonSql(id).then((v:any)=>sqlRows.value=v),assetApi.changes(id).then((v:any)=>changes.value=v),assetApi.relations(id).then((v:any)=>Object.assign(relations,v)),activityApi.recordView(id)])})
</script>

